  $j$[{"name": "t638.cjs on the build", "result": "28 pass, 0 fail: C1 42528 sol [3,4] to [3] with the DERIVED line; C2 the cases that leave the text equal and the cases that apply; C4 only Shared Library changes; C5 tags, no new catch", "source": "Wall 12057; rebuilt by W1, Wall 12059, 12070"}, {"name": "t638g.cjs, gate replay on sol's 42528 gate", "result": "5 pass, 0 fail: 13 gate items old and new, equal; 0 D38 items old and new; a synthetic case raises D38|BASIS|CHALLENGER|3", "source": "Wall 12061; reproduced by W1, Wall 12062, 12070"}, {"name": "Standing set with child aad0ad9c", "result": "31 PASS, 0 FAIL on the target (W4, W1), on the fetch-back (W4, Wall 12075) and on live 8470161f (W1, Wall 12076); pair Library Check PASSES; reg385 PASS", "source": "Wall 12069, 12070, 12075, 12076"}, {"name": "NOT RUN", "result": "any live call; 42373; the late gate", "source": "Wall 12062"}]$j$::jsonb,
